"use client";

import React from 'react';
import { motion} from "framer-motion";
import { usePrefersReducedMotion } from "./use-animation-hooks";
import { cn } from "@/lib/utils";

export interface MobileLoaderBorderBeamProps {
  className?: string;
  size?: number;
  strokeWidth?: number;
}

export const MobileLoaderBorderBeam: React.FC<MobileLoaderBorderBeamProps> = ({
  className,
  size = 64,
  strokeWidth = 3,
}) => {
  const prefersReducedMotion = usePrefersReducedMotion();
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;

  return (
    <div className={cn('relative flex items-center justify-center select-none', className)} style={{ width: size, height: size }}>
      <svg className="w-full h-full transform -rotate-90">
        {/* Track border */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          className="stroke-muted/20"
          strokeWidth={strokeWidth}
          fill="none"
        />

        {/* Glowing sweep laser */}
        <motion.circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          className="stroke-primary"
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          fill="none"
          strokeLinecap="round"
          style={{
            filter: 'drop-shadow(0 0 4px oklch(var(--p)))',
          }}
          animate={prefersReducedMotion ? {} : {
            strokeDashoffset: [circumference, 0],
          }}
          transition={prefersReducedMotion ? { duration: 0 } : {
            repeat: Infinity,
            duration: 1.5,
            ease: 'linear',
          }}
        />
      </svg>

      {/* Visual pulse inner */}
      <span className="absolute w-2 h-2 rounded-full bg-primary animate-ping" />
    </div>
  );
};

import { useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';

export const usePrefersReducedMotion = (): boolean => {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const listener = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', listener);
    return () => {
      mediaQuery.removeEventListener('change', listener);
    };
  }, []);

  return prefersReducedMotion;
};

export const useAnimateOnScroll = (options?: IntersectionObserverInit) => {
  const [ref, setRef] = useState<HTMLElement | null>(null);
  const [isIntersecting, setIsIntersecting] = useState(false);

  useEffect(() => {
    if (!ref) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry) {
        setIsIntersecting(entry.isIntersecting);
      }
    }, options);

    observer.observe(ref);
    return () => {
      observer.unobserve(ref);
    };
  }, [ref, options]);

  return [setRef, isIntersecting] as const;
};

export function useInView<T extends Element = HTMLDivElement>(
  options: IntersectionObserverInit = { rootMargin: '100px 0px', threshold: 0 },
): [RefObject<T | null>, boolean] {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === 'undefined' || !('IntersectionObserver' in window)) {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), options);
    io.observe(el);
    return () => io.disconnect();
  }, [options]);
  return [ref, inView];
}

export function useShouldAnimate<T extends Element = HTMLDivElement>(): [RefObject<T | null>, boolean] {
  const reduced = usePrefersReducedMotion();
  const [ref, inView] = useInView<T>();
  return [ref, inView && !reduced];
}
